// The generated registry files: their exact text. That Dart compiles and
// runs them is in codegen_compile_test.dart.

import 'package:just_asset_store/just_asset_store.dart';
import 'package:test/test.dart';

import 'support/codegen_items.dart';

void main() {
  test('modules, sorted by order then id, one alias per library', () {
    expect(
      StoreCodegen.modules([ui(), sprites(), kit()]),
      '// GENERATED by the Just Asset Store from just_store.lock.json.\n'
      '// Do not edit: install, update or remove items in the Asset Store,\n'
      '// or run `just store generate`.\n'
      '//\n'
      '// ignore_for_file: depend_on_referenced_packages, directives_ordering\n'
      '// ignore_for_file: unused_import\n'
      '\n'
      "import 'package:just_game_engine_editor/just_game_engine_editor.dart'\n"
      '    show EditorModule;\n'
      "import 'package:just_platformer_kit/editor.dart' as s0;\n"
      "import 'package:just_sprite_editor/editor.dart' as s1;\n"
      "import 'package:just_ui_editor/editor.dart' as s2;\n"
      '\n'
      '/// The editor modules of the items installed from the Asset\n'
      '/// Store, in the order they register.\n'
      'List<EditorModule> storeModules() => [\n'
      '  s0.PlatformerModule(),\n'
      '  s1.AnimatorModule(),\n'
      '  s1.SpriteStudioModule(),\n'
      '  s2.UiEditorModule(),\n'
      '];\n',
    );
  });

  test('the same items in any order give the same text', () {
    expect(
      StoreCodegen.modules([kit(), ui(), sprites()]),
      StoreCodegen.modules([sprites(), kit(), ui()]),
    );
    expect(
      StoreCodegen.extensions([kit(), ui()]),
      StoreCodegen.extensions([ui(), kit()]),
    );
  });

  test('nothing installed gives empty lists', () {
    expect(
      StoreCodegen.modules(const []),
      contains('List<EditorModule> storeModules() => [];'),
    );
    expect(
      StoreCodegen.extensions(const []),
      contains('const List<ContextExtension> storeExtensions = [];'),
    );
  });
}
